export const GUIDES: Guide[] = deepen([...BASE_GUIDES, ...MORE_GUIDES, ...EXTRA_GUIDES]);

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
// Plain-language search: every word must appear somewhere in the guide's title, symptoms, keywords or category.
export function searchGuides(query: string, category?: CategoryId | ''): Guide[] {
  const words = norm(query).split(' ').filter(w => w.length > 1 && !['a', 'an', 'the', 'to', 'my', 'how', 'fix', 'repair', 'is', 'of', 'and', 'or', 'that', 'it', 'not', 'in'].includes(w));
  const pool = category ? GUIDES.filter(g => g.category === category) : GUIDES;
  if (!words.length) return pool;
  const scored = pool.map(g => {
    const hay = norm([g.title, g.symptoms, g.keywords.join(' '), CATEGORIES[g.category].label].join(' '));
    const hits = words.filter(w => hay.includes(w) || (w.endsWith('s') && hay.includes(w.slice(0, -1))) || (w.endsWith('ing') && hay.includes(w.slice(0, -3))));
    const title = words.filter(w => norm(g.title).includes(w)).length;
    return {g, hits: hits.length, title};
  }).filter(x => x.hits === words.length || (words.length > 2 && x.hits >= words.length - 1));
  return scored.sort((a, b) => b.hits - a.hits || b.title - a.title).map(x => x.g);
}
